import{_ as i}from"./chunks/Audio.COine8Wh.js";import{_ as r}from"./chunks/Tags.BJ536pW3.js";import{c as s,o,j as a,G as t,ae as n,a as l}from"./chunks/framework.Bw0Gm4PQ.js";const g=JSON.parse('{"title":"ACES Act of 2025","description":"","frontmatter":{"legisId":"2025-08-14-aces-act-of-2025","title":"ACES Act of 2025","displayTitle":"ACES Act of 2025","lawNumber":"119-32","billNumber":"S. 201","sourceUrl":"https://www.govinfo.gov/bulkdata/PLAW/119/public/PLAW-119publ32.xml","publishDate":"2025-08-14T00:00:00-05:00","industries":["healthcare","defense"],"agencies":["Department of Veterans Affairs","National Academies of Sciences, Engineering, and Medicine","Department of the Army","Department of the Navy","Department of the Air Force"],"head":[["script",{"type":"application/ld+json"},"[{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"BreadcrumbList\\",\\"itemListElement\\":[{\\"@type\\":\\"ListItem\\",\\"position\\":1,\\"name\\":\\"Home\\",\\"item\\":\\"https://vladroff.github.io/legis\\"},{\\"position\\":2,\\"@type\\":\\"ListItem\\",\\"name\\":\\"Congress Bills\\",\\"item\\":\\"https://vladroff.github.io/legis/congress-bills\\"},{\\"position\\":3,\\"@type\\":\\"ListItem\\",\\"name\\":\\"ACES Act of 2025\\",\\"item\\":\\"https://vladroff.github.io/legis/congress-bills/2025-08-14-aces-act-of-2025\\"}]},{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"Article\\",\\"headline\\":\\"ACES Act of 2025\\",\\"description\\":\\"Summaries of US legislation.\\",\\"url\\":\\"https://vladroff.github.io/legis/congress-bills/2025-08-14-aces-act-of-2025\\",\\"datePublished\\":\\"2025-08-14T00:00:00-05:00\\",\\"dateModified\\":1788887623000,\\"mainEntityOfPage\\":\\"https://vladroff.github.io/legis/congress-bills/2025-08-14-aces-act-of-2025\\",\\"author\\":{\\"@type\\":\\"Organization\\",\\"name\\":\\"Legis\\"},\\"publisher\\":{\\"@type\\":\\"Organization\\",\\"name\\":\\"Legis\\"}}]"]]},"headers":[],"relativePath":"congress-bills/2025-08-14-aces-act-of-2025.md","filePath":"congress-bills/2025-08-14-aces-act-of-2025.md","lastUpdated":1788887623000}'),c={name:"congress-bills/2025-08-14-aces-act-of-2025.md"},u=Object.assign(c,{setup(d){return(f,e)=>(o(),s("div",null,[e[0]||(e[0]=a("h1",{id:"aces-act-of-2025",tabindex:"-1"},[l("ACES Act of 2025 "),a("a",{class:"header-anchor",href:"#aces-act-of-2025","aria-label":'Permalink to "ACES Act of 2025"'},"​")],-1)),t(i),t(r,{list:"/congress-bills"}),e[1]||(e[1]=n('<p>Signed into law on Thursday, August 14, 2025. Public Law 119-32, S. 201.</p><p><strong>Headline:</strong> The law orders an independent study of cancer rates and deaths among former military fixed-wing aircrew.</p><p><strong>Why it matters:</strong> The study will assess whether occupational exposures faced by military aircrew are associated with cancer and provide findings to the Department of Veterans Affairs and Congress.</p><p><strong>What the law does:</strong></p><ul><li>Directs the Department of Veterans Affairs to seek an agreement with the National Academies within 30 days and generally finalize it within 60 days after negotiations begin.</li><li>Requires delay explanations and progress briefings to the House and Senate Veterans’ Affairs Committees at least every 60 days if the agreement is not timely completed.</li><li>Requires researchers to identify chemical, environmental, and other occupational exposures linked to military aircrew service.</li><li>Reviews evidence connecting those exposures to overall cancer illness, cancer deaths, and specified cancers, including brain, lung, prostate, testicular, thyroid, and bladder cancers.</li><li>Uses available federal health, military, mortality, and prior study data to estimate cancer prevalence and deaths where possible.</li><li>Requires a final report to the Department of Veterans Affairs and Congress.</li></ul><p><strong>Who it affects:</strong></p><ul><li>Former active-duty Army, Navy, Air Force, and Marine Corps members who regularly served aboard fixed-wing aircraft.</li><li>Pilots, navigators, systems operators, and other covered aircrew members.</li><li>Federal officials responsible for veterans’ health policy and congressional oversight.</li></ul><p><strong>Practical impact on a regular person:</strong></p><ul><li>Covered veterans and their families may gain clearer information about cancer patterns associated with fixed-wing aircrew service.</li><li>The law commissions research and reporting but does not itself create new health benefits or compensation.</li></ul><h2 id="breakdown" tabindex="-1">Breakdown <a class="header-anchor" href="#breakdown" aria-label="Permalink to &quot;Breakdown&quot;">​</a></h2><h3 id="aces-act-of-2025-1" tabindex="-1">ACES Act of 2025 <a class="header-anchor" href="#aces-act-of-2025-1" aria-label="Permalink to &quot;ACES Act of 2025&quot;">​</a></h3><p>The ACES Act of 2025 directs the Department of Veterans Affairs to arrange a National Academies study of cancer rates and cancer deaths among former active-duty fixed-wing aircrew members. The study will examine occupational exposures, their possible associations with specified cancers, and available health and mortality data, followed by a report to the Department and Congress.</p><p><strong>Key takeaways:</strong></p><ul><li>The Department of Veterans Affairs must seek an agreement with the National Academies within 30 days of enactment and generally finalize it within 60 days after negotiations begin.</li><li>If the agreement is delayed, the Department must explain the delay to the House and Senate Veterans’ Affairs Committees and provide progress briefings at least every 60 days.</li><li>The study must identify chemical, environmental, and other exposures associated with military aircrew occupations.</li><li>The National Academies must review research on links between those exposures and overall cancer illness, cancer deaths, and specified cancers such as brain, lung, prostate, testicular, thyroid, and bladder cancers.</li><li>The study must use available federal health, military, mortality, and prior study data to estimate cancer prevalence and mortality where possible.</li><li>Covered individuals include active-duty Army, Navy, Air Force, and Marine Corps members who regularly served aboard fixed-wing aircraft as pilots, navigators, systems operators, or other aircrew.</li></ul><p>Source: <a href="https://www.govinfo.gov/bulkdata/PLAW/119/public/PLAW-119publ32.xml" target="_blank" rel="noreferrer">https://www.govinfo.gov/bulkdata/PLAW/119/public/PLAW-119publ32.xml</a></p>',15))]))}});export{g as __pageData,u as default};
